-- Tabella Tenant
DROP TABLE IF EXISTS tenant cascade;

CREATE TABLE tenant(
	id int NOT NULL IDENTITY,
	descrizione varchar(255) NOT NULL,
	logo_url varchar(500),
	colore_primario varchar(7),
	colore_secondario varchar(7),
	slug varchar(255) UNIQUE,
	sinossi varchar(500),
	PRIMARY KEY (id)
);


DROP TABLE IF EXISTS cap cascade;

CREATE TABLE cap(
	id int NOT NULL IDENTITY,
	cap varchar(5) NOT NULL,
	PRIMARY KEY (id)
	);
	
	
DROP TABLE IF EXISTS comuni cascade;

CREATE TABLE comuni(
	id int NOT NULL IDENTITY,
	nome varchar(100) NOT NULL,
    COD_COMUNE_ISTAT varchar(6) NOT NULL,
    COD_CATAST_COMUNE varchar(4) NOT NULL,
    provincia varchar(2) NOT NULL,
    COD_PROV varchar(3) NOT NULL,
    DESC_PROV varchar(50) NOT NULL,
    COD_REG varchar(2) NOT NULL,
    DESC_REG varchar(50),
    stato varchar(50)NOT NULL ,
	PRIMARY KEY (id)
);


