-- Popola fk_tenant nei posti basandosi sulla catena aree->cimiteri
UPDATE posti SET fk_tenant = (SELECT cim.fk_tenant FROM aree a JOIN cimiteri cim ON a.fk_cimitero = cim.id WHERE a.id = posti.fk_area) WHERE fk_tenant IS NULL;
-- Variazione tipi sepoltura per grafici realistici
UPDATE posti SET fk_tipo_sepoltura = 2 WHERE id IN (5, 12, 14, 23, 28);
UPDATE posti SET fk_tipo_sepoltura = 3 WHERE id IN (7, 20, 30);
UPDATE posti SET fk_tipo_sepoltura = 4 WHERE id IN (10, 22, 32);
UPDATE posti SET fk_tipo_sepoltura = 5 WHERE id IN (13, 19);
UPDATE posti SET fk_tipo_sepoltura = 6 WHERE id IN (3, 25);


CREATE TABLE sepolture (
	id INT NOT NULL IDENTITY,
	fk_defunto INT NOT NULL,
	fk_posto INT NOT NULL,
	data_inizio DATE NOT NULL,
	data_fine DATE NULL,
	tipo_operazione VARCHAR(50) NOT NULL,
	note TEXT,
	data_insert DATE NULL,
	data_update DATE NULL,
	fk_user_modifier INT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY (fk_defunto) REFERENCES defunti (id),
	FOREIGN KEY (fk_posto) REFERENCES posti (id),
	FOREIGN KEY (fk_user_modifier) REFERENCES users (id)
);



DROP TABLE IF EXISTS cap_comuni;

CREATE TABLE cap_comuni(
	comune_id int NULL,
	cap_id int NULL,
	FOREIGN key(comune_id) references comuni (id),
	FOREIGN key(cap_id) references cap (id)
	);
  


